/* C has no coroutines. The stackful form via POSIX ucontext. */
#include <ucontext.h>
#include <stdlib.h>

#define STACK_SIZE (64 * 1024)

struct coro {
    ucontext_t ctx;
    char *stack;
    int done;
};

static struct coro c;

static void body(void) {
    /* an ordinary function suspending at any depth - no colouring */
    puts("part 1");
    swapcontext(&c.ctx, &main_ctx);      /* suspend: save state, return to caller */
    puts("part 2");                     /* resumed here later */
    c.done = 1;
}

void coro_init(struct coro *c) {
    c->stack = malloc(STACK_SIZE);
    getcontext(&c->ctx);
    c->ctx.uc_stack.ss_sp = c->stack;
    c->ctx.uc_stack.ss_size = STACK_SIZE;
    c->ctx.uc_link = &main_ctx;
    makecontext(&c->ctx, body, 0);
}
/* Stackless alternative: a switch on an enum, storing the locals in a struct.
   Portable, no stack cost, but the call chain must be rewritten by hand. */
